INSERT INTO public.topics(domain_id,slug,title,summary,difficulty,estimated_minutes,display_order) SELECT id,'ai-ml-dl','AI·머신러닝·딥러닝의 차이','AI는 지능적 과제를 다루는 넓은 분야이고, 머신러닝은 데이터로 규칙을 학습하며 딥러닝은 여러 층의 신경망을 쓰는 방법입니다.','beginner',30,1 FROM public.domains WHERE slug='ai-machine-learning' ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.topics(domain_id,slug,title,summary,difficulty,estimated_minutes,display_order) SELECT id,'ml-problem-framing','머신러닝 문제 정의와 기준선','업무 문제를 예측 대상·결정 시점·오류 비용으로 바꾸고 단순한 기준선과 비교합니다.','beginner',30,2 FROM public.domains WHERE slug='ai-machine-learning' ON CONFLICT (slug) DO NOTHING;
