INSERT INTO public.topics(domain_id,slug,title,summary,difficulty,estimated_minutes,display_order) SELECT id,'vectors-matrices-tensors','벡터·행렬·텐서와 차원','모델의 자료와 연산은 여러 축을 가진 숫자 배열로 표현하며 각 축의 의미와 크기를 맞춰야 합니다.','intermediate',45,1 FROM public.domains WHERE slug='deep-learning' ON CONFLICT (slug) DO NOTHING;
