INSERT INTO public.topics(domain_id,slug,title,summary,difficulty,estimated_minutes,display_order) SELECT id,'neural-networks-backprop','신경망·활성화 함수·역전파','신경망은 선형 연산과 비선형 함수를 층으로 쌓고 역전파로 각 파라미터의 기울기를 계산합니다.','intermediate',45,3 FROM public.domains WHERE slug='deep-learning' ON CONFLICT (slug) DO NOTHING;
