INSERT INTO public.topics(domain_id,slug,title,summary,difficulty,estimated_minutes,display_order) SELECT id,'convolution-vision','컴퓨터 비전·합성곱·이미지 전처리','이미지는 공간 구조를 가진 숫자 배열이며 합성곱은 같은 작은 필터를 여러 위치에 적용해 특징을 추출합니다.','intermediate',45,5 FROM public.domains WHERE slug='deep-learning' ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.topics(domain_id,slug,title,summary,difficulty,estimated_minutes,display_order) SELECT id,'sequences-nlp','자연어 처리·시퀀스·마스킹','문장과 시계열은 순서와 길이가 의미를 가지므로 패딩·위치·유효 범위를 함께 다뤄야 합니다.','intermediate',45,6 FROM public.domains WHERE slug='deep-learning' ON CONFLICT (slug) DO NOTHING;
