INSERT INTO public.topics(domain_id,slug,title,summary,difficulty,estimated_minutes,display_order) SELECT id,'reinforcement-learning','강화학습·보상·정책','강화학습은 행동이 다음 상태와 보상에 미치는 영향을 이용해 장기적인 행동 전략을 학습합니다.','advanced',60,10 FROM public.domains WHERE slug='deep-learning' ON CONFLICT (slug) DO NOTHING;
