INSERT INTO public.topics(domain_id,slug,title,summary,difficulty,estimated_minutes,display_order) SELECT id,'llm-pretraining','LLM의 사전학습·후속 학습·추론','언어 모델은 문맥에서 다음 토큰을 예측하도록 학습하며 후속 학습으로 지시 응답 등을 조정하고 추론 때 문맥을 바탕으로 출력을 만듭니다.','beginner',30,1 FROM public.domains WHERE slug='generative-ai' ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.topics(domain_id,slug,title,summary,difficulty,estimated_minutes,display_order) SELECT id,'tokens-context-windows','토큰·문맥 창·잘림과 생성 길이','모델은 글자 수가 아닌 토큰으로 입력과 출력을 다루며 문맥 예산을 넘으면 필요한 정보가 누락되거나 요청이 실패할 수 있습니다.','beginner',30,2 FROM public.domains WHERE slug='generative-ai' ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.topics(domain_id,slug,title,summary,difficulty,estimated_minutes,display_order) SELECT id,'prompting-instructions','프롬프트·지시·예시와 검증','좋은 프롬프트는 과제·입력·출력 기준과 예시를 명확히 하고 실제 결과로 개선합니다.','beginner',30,3 FROM public.domains WHERE slug='generative-ai' ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.topics(domain_id,slug,title,summary,difficulty,estimated_minutes,display_order) SELECT id,'structured-outputs','구조화 출력·JSON Schema·의미 검증','모델 출력을 프로그램이 쓰려면 형식 제약과 파싱뿐 아니라 업무상 값의 의미도 검증해야 합니다.','intermediate',45,4 FROM public.domains WHERE slug='generative-ai' ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.topics(domain_id,slug,title,summary,difficulty,estimated_minutes,display_order) SELECT id,'embeddings-similarity','임베딩·벡터 유사도와 검색','임베딩은 자료를 숫자 벡터로 표현해 가까움을 계산하지만 유사도 점수는 사실성이나 권한의 증명이 아닙니다.','intermediate',45,5 FROM public.domains WHERE slug='generative-ai' ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.topics(domain_id,slug,title,summary,difficulty,estimated_minutes,display_order) SELECT id,'rag-retrieval','RAG·검색 증강 생성의 전체 흐름','RAG는 필요한 외부 자료를 검색해 모델의 문맥에 넣고 그 근거로 답하도록 구성하는 방식입니다.','intermediate',45,6 FROM public.domains WHERE slug='generative-ai' ON CONFLICT (slug) DO NOTHING;
