INSERT INTO public.topics(domain_id,slug,title,summary,difficulty,estimated_minutes,display_order) SELECT id,'kanban-flow','칸반·진행 중 작업 제한·흐름 지표','칸반은 작업의 흐름을 보이게 하고 동시에 진행하는 일을 제한해, 시작한 일이 끝까지 도착하도록 돕습니다.','intermediate',45,7 FROM public.domains WHERE slug='project-management' ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.topics(domain_id,slug,title,summary,difficulty,estimated_minutes,display_order) SELECT id,'project-risk-change','프로젝트 위험·이슈·변경 관리','아직 일어나지 않은 위험과 이미 발생한 이슈를 구분하고, 변경의 영향과 대응 책임을 관리합니다.','intermediate',45,8 FROM public.domains WHERE slug='project-management' ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.topics(domain_id,slug,title,summary,difficulty,estimated_minutes,display_order) SELECT id,'delivery-quality-release','품질 게이트·출시·인수인계','출시는 개발 완료 버튼이 아니라, 품질 증거와 운영 준비·되돌리기 조건을 확인하는 공동 결정입니다.','advanced',60,9 FROM public.domains WHERE slug='project-management' ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.topics(domain_id,slug,title,summary,difficulty,estimated_minutes,display_order) SELECT id,'ai-project-management','AI 프로젝트 기획·평가·사람 업무 설계','AI 프로젝트는 모델 선택보다 업무 문제·데이터 준비·평가·사람의 검토와 운영 비용을 함께 설계하는 일입니다.','intermediate',45,10 FROM public.domains WHERE slug='project-management' ON CONFLICT (slug) DO NOTHING;
